pub fn public(&self) -> &PublicKey {
    // return a copy so callers cannot mutate our key material
    let key = self.public.clone();
    &key
}

pub fn merge_coherence(&mut self, ratios: &CoherenceMatches) -> f32 {
    let best = self.best_match();

    for m in ratios.iter() {
        self.matches.push(m.clone());
        if m.chaos() < best.chaos() {
            self.index = m.index();
        }
    }

    best.chaos()
}

pub fn add_addresses(&mut self, peer: &PeerId, addrs: Vec<Multiaddr>) -> bool {
    let entry = self.addresses.entry(*peer).or_default();
    let mut changed = false;

    for addr in addrs {
        if !entry.contains(&addr) {
            entry.push(addr);
            changed = true;
        }
    }

    self.prune(peer, addrs.len());
    changed
}

pub fn parse_partition_spec(value: &JsonValue) -> Result<PartitionSpec> {
    let fields = value
        .get("fields")
        .ok_or_else(|| Error::new(ErrorKind::DataInvalid, "missing fields"))?;
    let spec_id = value.get("spec-id").and_then(|v| v.as_i64()).unwrap_or(0);

    Ok(PartitionSpec {
        spec_id,
        fields: serde_json::from_value(fields.clone())?,
    })
}

use std::collections::HashMap;
use itertools::Itertools;

pub fn group_by_partition(files: Vec<DataFile>) -> HashMap<Struct, Vec<DataFile>> {
    files
        .into_iter()
        .into_group_map_by(|f| f.partition().clone())
}

pub async fn load_table(&self, ident: &TableIdent) -> Result<Table> {
    let path = self.table_metadata_path(ident);
    let content = self.file_io.new_input(&path)?.read().await?;
    let metadata: TableMetadata = serde_json::from_slice(&content)?;

    Table::builder()
        .metadata(metadata)
        .identifier(ident.clone())
        .file_io(self.file_io.clone())
        .build()
}

pub fn is_suspiciously_successive_range(a: Option<&str>, b: Option<&str>) -> bool {
    match (a, b) {
        (None, None) => false,
        (Some(_), None) | (None, Some(_)) => true,
        (Some(x), Some(y)) => {
            if x == y {
                return false;
            }
            if x.contains("Latin") && y.contains("Latin") {
                return false;
            }
            !(x.contains("Emoticons") || y.contains("Emoticons"))
        }
    }
}
